int alive = FUZZ_GET_ATTR_INT(cfg, "alive");
if (alive != 1) { FUZZ_BAIL(); }

// Invoke shutdown; after this call cfg must not be used again
rtpp_shutdown(cfg);

// Mark as dead for safety; do not return cfg to the pool
FUZZ_SET_ATTR_INT(cfg, "alive", 0);

// Validation summary: Ensures cfg was previously initialized (alive==1), performs shutdown once, and drops the handle from outputs to avoid reuse.

// Generate argc in a small safe range [0, 8]
int argc = (int)(*FUZZ_PARAM(unsigned int) % 9);

// Build argv as an array of argc non-null, NUL-terminated C strings
// Each argument is constrained for size and has no embedded NULs
std::vector<std::string> arg_storage;
arg_storage.reserve((size_t)argc);
for (int i = 0; i < argc; ++i) {
    std::string s = FUZZ_PARAM_STR();
    // Constrain size for performance and to avoid giant allocations
    if (s.size() > 128) s.resize(128);
    // Remove embedded NULs so each argument is a well-formed C string
    for (size_t j = 0; j < s.size(); ++j) {
        if (s[j] == '\0') s[j] = 'X';
    }
    // Ensure at least one printable char
    if (s.empty()) s = "x";
    arg_storage.emplace_back(std::move(s));
}

std::vector<const char *> argv_vec;
argv_vec.reserve((size_t)argc);
for (int i = 0; i < argc; ++i) {
    argv_vec.push_back(arg_storage[(size_t)i].c_str());
}

const char * const *argv_ptr = (argc > 0) ? (const char * const *)argv_vec.data() : (const char * const *)nullptr;

// Call the target function
struct rtpp_cfg *cfg = rtpp_main(argc, argv_ptr);

// Validate result: on failure, bail to avoid emitting a null handle into the pool
if (cfg == nullptr) { FUZZ_BAIL(); }

// Track lifetime: cfg is now alive and must be shut down exactly once later
FUZZ_SET_ATTR_INT(cfg, "alive", 1);

// Validation summary: Builds a valid argv array (or NULL when argc==0), calls rtpp_main,
// bails on NULL, and tags the returned cfg as alive for later rtpp_shutdown().

