import random
import string
from typing import List

# This generator produces a single buffer that the harness will slice into strings
# for FUZZ_PARAM_STR calls. We encode a sequence of argv-like tokens separated by\n
# newlines. The stub ensures strings are NUL-free and size-capped; we proactively
# avoid NULs and keep tokens reasonable, emphasizing valid and interesting rtpproxy
# command-line styles (flags, options with values, paths, addresses, ports, etc.).

PRINTABLE = ''.join(ch for ch in string.printable if ch not in ['\x0b', '\x0c', '\x0b', '\x0c'])
SAFE_CHARS = ''.join(ch for ch in PRINTABLE if ch != '\x00')

def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]

def _rand_token(rng: random.Random) -> str:
    # Generate a generic token of length 1..32
    length = rng.randint(1, 32)
    return ''.join(rng.choice(SAFE_CHARS[:-1]) for _ in range(length))

def _rand_int(rng: random.Random, lo: int, hi: int) -> str:
    return str(rng.randint(lo, hi))

def _addr(rng: random.Random) -> str:
    if rng.random() < 0.6:
        # IPv4
        return '.'.join(str(rng.randint(0, 255)) for _ in range(4))
    else:
        # Hostname
        labels = [
            ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(rng.randint(1, 8)))
            for _ in range(rng.randint(1, 3))
        ]
        tld = _rand_choice(rng, ['com', 'net', 'org', 'local', 'io'])
        return '.'.join(labels + [tld])

def _path(rng: random.Random) -> str:
    if rng.random() < 0.7:
        parts = [''] + [
            ''.join(rng.choice(string.ascii_letters + string.digits + '._-') for _ in range(rng.randint(1, 10)))
            for _ in range(rng.randint(1, 4))
        ]
        return '/'.join(parts) or '/'
    else:
        return './' + ''.join(rng.choice(string.ascii_letters + string.digits + '._-') for _ in range(rng.randint(1, 10)))

def _bool_flag(rng: random.Random) -> str:
    return _rand_choice(rng, [
        '-v', '--verbose', '-q', '--quiet', '-d', '--daemonize', '-h', '--help',
        '--no-log', '--single-thread', '--multi-thread'
    ])

def _opt_with_value(rng: random.Random) -> List[str]:
    # Options common to network/server daemons, inspired by typical rtpproxy-like CLIs
    opt = _rand_choice(rng, [
        '-l', '--listen',           # address
        '-p', '--port',             # port
        '-f', '--config',           # config file path
        '-P', '--pidfile',          # pid file path
        '-s', '--socket',           # control socket path
        '-m', '--max-sessions',     # number
        '-r', '--recording-dir',    # path
        '--log-level',              # level
        '--timeout',                # seconds
        '--control-ip',             # address
        '--control-port',           # port
        '--ttl',                    # hops
        '--user',                   # user name
        '--group',                  # group name
    ])
    if opt in ['-l', '--listen', '--control-ip']:
        val = _addr(rng)
    elif opt in ['-p', '--port', '--control-port']:
        val = _rand_int(rng, 1, 65535)
    elif opt in ['-m', '--max-sessions']:
        val = _rand_int(rng, 1, 100000)
    elif opt in ['--timeout', '--ttl']:
        val = _rand_int(rng, 1, 3600)
    elif opt in ['--log-level']:
        val = _rand_choice(rng, ['debug', 'info', 'notice', 'warn', 'error'])
    elif opt in ['-f', '--config', '-P', '--pidfile', '-s', '--socket', '-r', '--recording-dir']:
        val = _path(rng)
    elif opt in ['--user', '--group']:
        val = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 10)))
    else:
        val = _rand_token(rng)
    # Sometimes join with '=' like --opt=value
    if opt.startswith('--') and rng.random() < 0.5:
        return [opt + '=' + val]
    else:
        return [opt, val]

def _make_argv_tokens(rng: random.Random, argc: int) -> List[str]:
    tokens: List[str] = []
    if argc == 0:
        return tokens
    # argv[0]: program name
    prog = _rand_choice(rng, ['rtpproxy', 'rtpp', 'rtpproxyd', 'srv', 'app'])
    tokens.append(prog)
    # Remaining args
    i = 1
    while i < argc:
        choice = rng.random()
        if choice < 0.35 and i < argc:
            tokens.append(_bool_flag(rng))
            i += 1
        elif choice < 0.8 and i < argc:
            vals = _opt_with_value(rng)
            # Ensure we don't exceed argc; if too many, collapse into single token with '='
            if len(vals) == 2 and i == argc - 0:  # no room for two: collapse
                # convert to --opt=value if possible, otherwise single token
                opt = vals[0]
                val = vals[1]
                if opt.startswith('--'):
                    tokens.append(opt + '=' + val)
                    i += 1
                else:
                    tokens.append(opt)
                    i += 1
            else:
                for v in vals:
                    if i >= argc:
                        break
                    tokens.append(v)
                    i += 1
        else:
            tokens.append(_rand_token(rng))
            i += 1
    # Ensure no token is empty or contains NUL
    cleaned = []
    for t in tokens[:argc]:
        if not t:
            t = 'x'
        t = t.replace('\x00', 'X')
        # Limit token length to 120 (below harness cap 128)
        if len(t) > 120:
            t = t[:120]
        cleaned.append(t)
    return cleaned

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose argc in [0,8] to match harness range
    argc = rng.randint(0, 8)
    tokens = _make_argv_tokens(rng, argc)
    # Encode as newline-separated strings; harness will draw FUZZ_PARAM_STR items from this buffer.
    # Keep total size under 4096 bytes.
    blob = '\n'.join(tokens)
    data = blob.encode('utf-8')
    if len(data) > 4096:
        data = data[:4096]
    return data
